function pipe(...)
    local fns = table.pack(...)
    return function(x)
        for i = 1, fns.n do
            x = (fns[i](x))
        end
        return x
    end
end

function partial(fn, ...)
    local fixed = table.pack(...)
    return function(...)
        local more = table.pack(...)
        local args = {}
        for i = 1, fixed.n do args[i] = fixed[i] end
        for i = 1, more.n do args[fixed.n + i] = more[i] end
        return fn(table.unpack(args, 1, fixed.n + more.n))
    end
end
